  ('pages.blog.consultant-informatique-independant-galeres.auto.paragraph.u2k7no', '/blog/consultant-informatique-independant-galeres', 'paragraph', 'Racontez-nous votre situation : nous répondons avec vos chiffres et vos contraintes, pas avec des généralités.'),
