  ('pages.qui-sommes-nous.auto.paragraph.1bx7ktl', '/qui-sommes-nous', 'paragraph', 'Les missions peuvent concerner aussi bien la définition d’une stratégie de cybersécurité que la sécurisation opérationnelle des environnements cloud, des identités, des applications, des réseaux ou des données sensibles.'),
  ('pages.qui-sommes-nous.auto.paragraph.1carmwo', '/qui-sommes-nous', 'paragraph', 'L’approche en bref'),
