  ('pages.qui-sommes-nous.auto.paragraph.anj2l0', '/qui-sommes-nous', 'paragraph', 'Architecte Data'),
  ('pages.qui-sommes-nous.auto.paragraph.auhntg', '/qui-sommes-nous', 'paragraph', 'Conception de solutions basées sur les grands modèles de langage, assistants métiers, moteurs de recherche internes, systèmes RAG et automatisations intelligentes.'),
